var sortableIntegers = function(nums) {
    const n = nums.length;
    let res = 0;

    for (let k = 1; k <= n; k++) {
        if (n % k === 0) {
            const partitions = [];
            let cur = [];

            for (let i = 0; i < n; i++) {
                if (cur.length < k) {
                    cur.push(nums[i]);
                } else {
                    partitions.push(cur);
                    cur = [nums[i]];
                }
            }
            partitions.push(cur);

            let isSortable = true;
            let lastMax = 0;

            for (let i = 0; i < partitions.length; i++) {
                const len = partitions[i].length;
                let cuts = 0;
                let max = 0;

                for (let j = 0; j < len; j++) {
                    max = Math.max(max, nums[j]);

                    if (partitions[i][j] < lastMax) {
                        cuts = 2;
                        break;
                    }

                    if (partitions[i][j] > partitions[i][(j + 1) % len]) {
                        cuts++;

                        if (cuts > 1) {
                            break;
                        }
                    }
                }

                if (cuts > 1) {
                    isSortable = false;
                    break;
                }

                lastMax = max;
            }

            if (isSortable) {
                res += k;
            }
        }
    }

    return res;
};

